  "code": "def correct_bracketing(brackets: str) -> bool:
    """ This function verifies if the provided string of brackets is correctly formatted.
    It returns True if all opening brackets have a matching closing bracket.

    >>> correct_bracketing("<>")
    True
    >>> correct_bracketing("<<><>>")
    True
    >>> correct_bracketing("><<>")
    False
    """
    stack = []
    bracket_pairs = {')': '(', ']': '[', '}': '{', '>': '<'}

    for bracket in brackets:
        if bracket in bracket_pairs.values():
            stack.append(bracket)
        elif bracket in bracket_pairs.keys():
            if not stack or stack.pop() != bracket_pairs[bracket]:
                return False
        else:
            return False

    return not stack",
